//! Parity between the speak command in `voxr_narrate` ([`prepare_speak`],
//! [`finish_speak`]) and the skill's own `speakCmd`.
//!
//! The fixture (`tests/fixtures/narration_command_speak_oracle.json`) is
//! checked in and was generated by
//! `tests/tools/narration_oracle/command_speak.mjs`, which runs `speakCmd`
//! from video.mjs with `speak()` stubbed: it records its call, writes the
//! scenario's signal as the voiceover and returns the scenario's result.
//! Each scenario here replays the same files, flags, config and readiness
//! through `prepare_speak`, the same stub result through `finish_speak`,
//! and compares the `speak()` call, every printed line with its stream,
//! the exit code or the error, and every file left.

use std::path::Path;

use serde::Deserialize;
use serde_json::{Map, Value, json};
use voxr_narrate::{
    CommandError, FinishInputs, HeardWord, Line, PartCheck, PreparedSpeak, ScriptChecks,
    SpeakFlags, SpokenScript, Stream, TtsConfig, WholeCheck, finish_speak, pcm16_wav,
    prepare_speak, read_wav_file,
};

mod common;
use common::signals::fnv1a_bytes;
use common::take_files::{OpJson, render_json};
use common::{assert_oracle_current, load_json};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_command_speak_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/command_speak.mjs"
);

#[derive(Debug, Deserialize)]
struct Fixture {
    rate: u32,
    scenarios: Vec<Scenario>,
}

#[derive(Debug, Deserialize)]
struct Ready {
    ok: bool,
    why: String,
}

#[derive(Debug, Deserialize)]
struct Signal {
    n: usize,
    ops: Vec<OpJson>,
}

#[derive(Debug, Deserialize)]
struct Scenario {
    name: String,
    files: Map<String, Value>,
    args: Value,
    config: Value,
    ready: Ready,
    wav: Option<Signal>,
    result: Option<Value>,
    output: Output,
}

#[derive(Debug, Deserialize)]
struct Output {
    calls: Vec<Value>,
    lines: Vec<LineJson>,
    code: Option<i32>,
    failure: Option<Failure>,
    files: Vec<FileJson>,
}

#[derive(Debug, Deserialize, PartialEq)]
struct LineJson {
    stream: String,
    text: String,
}

#[derive(Debug, Deserialize)]
struct Failure {
    input: bool,
    message: String,
}

#[derive(Debug, Deserialize, PartialEq)]
struct FileJson {
    path: String,
    text: Option<String>,
    bytes: Option<String>,
}

fn text(v: &Value, key: &str) -> Option<String> {
    v[key].as_str().map(str::to_string)
}

fn flags(args: &Value) -> SpeakFlags {
    SpeakFlags {
        script: args["rest"]
            .as_array()
            .map(|r| {
                r.iter()
                    .filter_map(|s| s.as_str().map(str::to_string))
                    .collect()
            })
            .unwrap_or_default(),
        engine: text(args, "engine"),
        voice: text(args, "voice"),
        style: text(args, "style"),
        reference: text(args, "reference"),
        speed: args["speed"].as_f64(),
        pace: args["pace"].as_f64(),
        seed: args["seed"].as_f64(),
        reroll: args["reroll"].as_array().map(|r| {
            r.iter()
                .filter_map(Value::as_u64)
                .map(|n| n as usize)
                .collect()
        }),
        cfg: args["cfg"].as_f64(),
        steps: args["steps"].as_u64().map(|n| n as u32),
        hifi: args["hifi"].as_bool().unwrap_or(false),
        written: text(args, "written"),
        review: args["review"].as_bool().unwrap_or(false),
        raw: args["raw"].as_bool().unwrap_or(false),
        device: text(args, "device"),
        language: text(args, "language"),
        model: text(args, "model"),
        command: text(args, "command"),
        one_call: args["oneCall"].as_bool().unwrap_or(false),
        out: text(args, "out"),
    }
}

fn tts(tts: &Value) -> TtsConfig<'_> {
    TtsConfig {
        engine: tts["engine"].as_str(),
        command: tts["command"].as_str(),
        model: tts["model"].as_str(),
        voice: tts["voice"].as_str(),
        speed: tts["speed"].as_f64(),
        reference: tts["reference"].as_str(),
        style: tts["style"].as_str(),
        hifi: tts["hifi"].as_bool(),
        cfg: tts["cfg"].as_f64(),
        steps: tts["steps"].as_u64().map(|n| n as u32),
        seed: tts["seed"].as_f64(),
        one_call: tts["oneCall"].as_bool(),
    }
}

/// `text` with `dir` written as `<dir>`.
fn normalize(text: &str, dir: &Path) -> String {
    text.replace(&dir.to_string_lossy().into_owned(), "<dir>")
}

/// The options `speak()` receives, as the stub records them.
fn call(prepared: &PreparedSpeak, f: &SpeakFlags, dir: &Path) -> Value {
    let o = prepared.opts(f);
    let mut m = Map::new();
    let mut put = |k: &str, v: Option<Value>| {
        if let Some(v) = v {
            m.insert(k.to_string(), v);
        }
    };
    put("voice", o.voice.map(|v| json!(v)));
    put("speed", o.speed.map(|v| json!(v)));
    put("model", o.model.map(|v| json!(v)));
    put("command", o.command.map(|v| json!(v)));
    put("engine", o.engine.map(|v| json!(v)));
    put("reference", o.reference.map(|v| json!(normalize(v, dir))));
    put("device", o.device.map(|v| json!(v)));
    put("seed", o.seed.map(|v| json!(v)));
    put("language", o.language.map(|v| json!(v)));
    put(
        "cues",
        o.cues.map(|c| {
            Value::Array(
                c.iter()
                    .map(|c| json!({"start": c.start, "end": c.end, "text": c.text}))
                    .collect(),
            )
        }),
    );
    put("reroll", f.reroll.as_ref().map(|r| json!(r)));
    put("oneCall", o.one_call.map(|v| json!(v)));
    put("style", o.style.map(|v| json!(v)));
    put("cfg", o.cfg.map(|v| json!(v)));
    put("steps", o.steps.map(|v| json!(v)));
    put("hifi", o.hifi.map(|v| json!(v)));
    json!({
        "script": prepared.script,
        "out": normalize(&prepared.out.to_string_lossy(), dir),
        "opts": Value::Object(m),
    })
}

/// `v` with every number as a float, so `3` and `3.0` compare equal.
fn canon(v: &Value) -> Value {
    match v {
        Value::Number(n) => json!(n.as_f64()),
        Value::Array(a) => Value::Array(a.iter().map(canon).collect()),
        Value::Object(m) => Value::Object(m.iter().map(|(k, v)| (k.clone(), canon(v))).collect()),
        other => other.clone(),
    }
}

/// The stub's result as `speak()` returns it.
fn spoken(result: &Value) -> SpokenScript {
    let checks = result["checks"].as_array().cloned().unwrap_or_default();
    let parts = checks.iter().any(|c| c.get("seed").is_some());
    let checks = if parts {
        ScriptChecks::Parts(
            checks
                .iter()
                .map(|c| PartCheck {
                    at: c["at"].as_f64().unwrap_or_default(),
                    text: text(c, "text").unwrap_or_default(),
                    ok: c["ok"].as_bool().unwrap_or_default(),
                    heard: text(c, "heard").unwrap_or_default(),
                    why: text(c, "why").unwrap_or_default(),
                    seed: c["seed"].as_f64().unwrap_or_default(),
                    doubt: serde_json::from_value(c["doubt"].clone()).unwrap_or_default(),
                    heat: c["heat"].as_f64().unwrap_or_default(),
                    hot_text: text(c, "hotText"),
                    pauses: serde_json::from_value(c["pauses"].clone()).unwrap_or_default(),
                    clicks: serde_json::from_value(c["clicks"].clone()).unwrap_or_default(),
                })
                .collect(),
        )
    } else {
        ScriptChecks::Whole(
            checks
                .iter()
                .map(|c| WholeCheck {
                    at: c["at"].as_f64().unwrap_or_default(),
                    text: text(c, "text").unwrap_or_default(),
                    ok: c["ok"].as_bool().unwrap_or_default(),
                    heard: text(c, "heard").unwrap_or_default(),
                    why: text(c, "why").unwrap_or_default(),
                    doubt: serde_json::from_value(c["doubt"].clone()).unwrap_or_default(),
                    pauses: serde_json::from_value(c["pauses"].clone()).unwrap_or_default(),
                })
                .collect(),
        )
    };
    let phrases: Option<Vec<HeardWord>> = result
        .get("phrases")
        .map(|p| serde_json::from_value(p.clone()).unwrap_or_else(|e| panic!("phrases: {e}")));
    SpokenScript {
        duration: result["duration"].as_f64().unwrap_or_default(),
        phrases,
        engine: text(result, "engine").unwrap_or_default(),
        checks,
        problems: serde_json::from_value(result["problems"].clone()).unwrap_or_default(),
        timing: result
            .get("timing")
            .map(|t| serde_json::from_value(t.clone()).unwrap_or_default()),
        voice_file: result.get("voiceFile").map(|_| None),
    }
}

/// Every file under `root`, as the oracle lists them.
fn files(root: &Path, dir: &Path) -> Vec<FileJson> {
    let mut out = Vec::new();
    let mut dirs = vec![root.to_path_buf()];
    while let Some(d) = dirs.pop() {
        for entry in
            std::fs::read_dir(&d).unwrap_or_else(|e| panic!("listing {}: {e}", d.display()))
        {
            let path = entry.unwrap_or_else(|e| panic!("{e}")).path();
            if path.is_dir() {
                dirs.push(path);
                continue;
            }
            let rel = path
                .strip_prefix(root)
                .unwrap_or_else(|e| panic!("{e}"))
                .components()
                .map(|c| c.as_os_str().to_string_lossy().into_owned())
                .collect::<Vec<_>>()
                .join("/");
            let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("{e}"));
            out.push(if rel.ends_with(".wav") {
                FileJson {
                    path: rel,
                    text: None,
                    bytes: Some(fnv1a_bytes(&bytes)),
                }
            } else {
                FileJson {
                    path: rel,
                    text: Some(normalize(&String::from_utf8_lossy(&bytes), dir)),
                    bytes: None,
                }
            });
        }
    }
    out.sort_by(|a, b| a.path.cmp(&b.path));
    out
}

fn line_json(l: &Line, dir: &Path) -> LineJson {
    LineJson {
        stream: match l.stream {
            Stream::Out => "out",
            Stream::Err => "err",
        }
        .to_string(),
        text: normalize(&l.text, dir),
    }
}

fn run(s: &Scenario, rate: u32) {
    let root = tempfile::tempdir().unwrap_or_else(|e| panic!("{e}"));
    let dir = root.path();
    for (path, content) in &s.files {
        let p = dir.join(path);
        if let Some(parent) = p.parent() {
            std::fs::create_dir_all(parent).unwrap_or_else(|e| panic!("{e}"));
        }
        std::fs::write(&p, content.as_str().unwrap_or_default()).unwrap_or_else(|e| panic!("{e}"));
    }
    let f = flags(&s.args);
    let tts_cfg = tts(&s.config["tts"]);
    let mut lines = Vec::new();
    let mut calls = Vec::new();
    let outcome = (|| -> Result<i32, CommandError> {
        let prepared = prepare_speak(&f, &tts_cfg, s.ready.ok, &s.ready.why, dir, &mut lines)?;
        if prepared.review_only {
            return Ok(0);
        }
        calls.push(call(&prepared, &f, dir));
        let (Some(wav), Some(result)) = (&s.wav, &s.result) else {
            panic!("scenario {} reaches speak() with no stub result", s.name);
        };
        if let Some(parent) = prepared.out.parent() {
            std::fs::create_dir_all(parent).unwrap_or_else(|e| panic!("{e}"));
        }
        let samples = render_json(wav.n, &wav.ops);
        let bytes = pcm16_wav(&samples, rate).unwrap_or_else(|e| panic!("{e}"));
        std::fs::write(&prepared.out, bytes).unwrap_or_else(|e| panic!("{e}"));
        let run = spoken(result);
        let inputs = FinishInputs {
            flags: &f,
            prepared: &prepared,
            tts: &tts_cfg,
            tts_pace: s.config["tts"]["pace"].as_f64(),
            cwd: dir,
        };
        let mut decode = |p: &Path| read_wav_file(p).map(|t| t.samples);
        Ok(finish_speak(&run, &inputs, &mut decode, &mut lines)?.code)
    })();
    let name = &s.name;
    let want: Vec<Value> = s.output.calls.iter().map(canon).collect();
    let got_calls: Vec<Value> = calls.iter().map(canon).collect();
    assert_eq!(got_calls, want, "speak() calls, scenario {name}");
    let got: Vec<LineJson> = lines.iter().map(|l| line_json(l, dir)).collect();
    assert_eq!(got, s.output.lines, "lines, scenario {name}");
    match (&outcome, &s.output.failure) {
        (Ok(code), None) => assert_eq!(Some(*code), s.output.code, "exit code, scenario {name}"),
        (Err(e), Some(want)) => {
            assert_eq!(
                matches!(e, CommandError::Input(_)),
                want.input,
                "error kind, scenario {name}: {e}"
            );
            assert_eq!(
                normalize(e.message(), dir),
                want.message,
                "error, scenario {name}"
            );
        }
        (got, want) => panic!("scenario {name}: got {got:?}, want {want:?}"),
    }
    assert_eq!(files(dir, dir), s.output.files, "files, scenario {name}");
}

#[test]
fn speak_command_matches_javascript_on_every_scenario() {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    assert!(!fixture.scenarios.is_empty(), "fixture must not be empty");
    for s in &fixture.scenarios {
        run(s, fixture.rate);
    }
}

#[test]
fn speak_command_oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}
